def selection_sort(values):
    for start in range(len(values) - 1):
        smallest = start
        for index in range(start + 1, len(values)):
            if values[index] < values[smallest]:
                smallest = index
        if smallest != start:
            values[start], values[smallest] = values[smallest], values[start]
    return values

def insertion_sort(values):
    for index in range(1, len(values)):
        item = values[index]
        position = index - 1
        while position >= 0 and values[position] > item:
            values[position + 1] = values[position]
            position -= 1
        values[position + 1] = item
    return values

print(selection_sort([3, 1, 2]))
print(insertion_sort([2, 4, 3, 1]))
print(insertion_sort([]))

def selection_sort_in_place(values):
    for start in range(len(values) - 1):
        smallest = start
        for index in range(start + 1, len(values)):
            if values[index] < values[smallest]:
                smallest = index
        if smallest != start:
            values[start], values[smallest] = values[smallest], values[start]

for values in [[3, 1, 2], [], [2, 2, 1]]:
    result = selection_sort_in_place(values)
    print(result, values)

def selection_comparisons(values):
    result = list(values)
    comparisons = 0
    for start in range(len(result) - 1):
        smallest = start
        for index in range(start + 1, len(result)):
            comparisons += 1
            if result[index] < result[smallest]:
                smallest = index
        if smallest != start:
            result[start], result[smallest] = result[smallest], result[start]
    return result, comparisons

print(selection_comparisons([3, 1, 2]))
print(selection_comparisons([1, 2, 3]))
print(selection_comparisons([]))
print(selection_comparisons([8]))
